With(
    {
        // FASE 1: Buscamos el curso y contamos operarios
        NumeroOperarios: CountRows(Gallery1.AllItems),
        CursoAnual: LookUp(
            'Cursos Formativos', 
            Title = Curso_Formativo_1.Selected.Value && Plan_Form = Plan_Formativo_1.Selected.Value
        )
    },
    
    With(
        {
            // FASE 2: PURIFICACIÓN
            IdPuro: Value(CursoAnual.ID_CURSO_UNICO) 
        },
        
        With(
            {
                // FASE 3: Búsqueda delegable
                HorasDelCurso: Value(
                    LookUp(
                        CursosFormativosUnicos, 
                        ID_CURSO = IdPuro 
                    ).HORAS
                )
            },
            
            If(
                IsBlank(HorasDelCurso),
                "El curso no está correctamente configurado",
                NumeroOperarios * HorasDelCurso
            )
        )
    )
)
